package app.dayflow;import android.content.Context;import org.json.*;import java.io.*;import android.util.AtomicFile;
final class EditorSnapshot {static String write(Context c,JSONObject r){String id=r.optString("id");try{java.util.UUID.fromString(id);File folder=new File(c.getFilesDir(),"editor-state");folder.mkdirs();AtomicFile target=new AtomicFile(new File(folder,id+".json"));FileOutputStream stream=null;try{stream=target.startWrite();Writer out=new OutputStreamWriter(stream,java.nio.charset.StandardCharsets.UTF_8);out.write(r.toString());out.flush();target.finishWrite(stream);}catch(Exception e){if(stream!=null)target.failWrite(stream);throw e;}return id;}catch(Exception e){return "";}}static void clear(Context c,String id){try{java.util.UUID.fromString(id);new AtomicFile(new File(new File(c.getFilesDir(),"editor-state"),id+".json")).delete();}catch(Exception ignored){}}static JSONObject read(Context c,String id)throws Exception{java.util.UUID.fromString(id);try(InputStream in=new AtomicFile(new File(new File(c.getFilesDir(),"editor-state"),id+".json")).openRead()){return new JSONObject(MarkdownFiles.read(in));}}}
